impl<T: gx::Real> Quadvector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[4];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t4);
        let t7 = t3.mul_add(T::from_i64(2), t5);
        let t8 = -t7;
        t8
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (26 mul, 12 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Quadvector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[4];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t14);
        let t16 = t0.mul_add(t1, t6);
        let t17 = t1.mul_add(t2, t16);
        let t19 = t0.mul_add(t3, t10);
        let t20 = t2.mul_add(t3, t13);
        let t21 = t19 + t20;
        let t23 = t17.mul_add(T::from_i64(2), t15);
        let t24 = t21.mul_add(T::from_i64(4), t23);
        let t25 = t24.recip();
        let t27 = t1 * t25;
        let t29 = t3 * t25;
        let t30 = t0.mul_add(t25, t27);
        let t31 = t2.mul_add(t25, t30);
        let t33 = t29.mul_add(T::from_i64(2), t31);
        let t34 = x[0] * t33;
        let t35 = x[1] * t33;
        let t36 = x[2] * t33;
        let t37 = x[3] * t33;
        let t38 = x[4] * t33;
        let t39 = -t34;
        let t40 = -t35;
        let t41 = -t36;
        let t42 = -t37;
        let t43 = -t38;
        Quadvector::from_coeffs([t39, t40, t41, t42, t43])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[3] * x[4];
        let p4 = x[0].mul_add(x[0], p1);
        let p5 = x[2].mul_add(x[2], p4);
        let p7 = p3.mul_add(T::from_i64(2), p5);
        let p8 = -p7;
        let s0 = (p8).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        gx::Unit::new_unchecked(Quadvector::from_coeffs([t0, t1, t2, t3, t4]))
    }

}

#[doc = "The pseudoscalar `e123oi`."]
///
/// Blades, in coefficient order: `[e123oi]`.
///
/// `S` lists the open slots: `Pseudoscalar` (that is, `Pseudoscalar<()>`) is a value, `Pseudoscalar<(A,)>` a
/// linear map from `A`, `Pseudoscalar<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Pseudoscalar<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 1],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Pseudoscalar<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Pseudoscalar<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Pseudoscalar<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Pseudoscalar<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Pseudoscalar");
        for (b, c) in <Pseudoscalar as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Pseudoscalar {
    const N: usize = 1;
    const NAME: &'static str = "Pseudoscalar";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e123oi"];
    type Arr<X: gx::Elem> = [X; 1];
    type Mv<S: gx::Slots, T: gx::Coef> = Pseudoscalar<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(f: impl FnMut(usize) -> X) -> [X; 1] {
        core::array::from_fn(f)
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 1], f: impl FnMut(&X) -> Y) -> [Y; 1] {
        a.each_ref().map(f)
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 1],
        b: &[Y; 1],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 1] {
        core::array::from_fn(|i| f(&a[i], &b[i]))
    }
}

