impl<S: gx::Slots, T: gx::Coef> gx::Transform<Scalar<S, T>> for Motor<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Scalar<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 1>(&x.c) {
        let t1 = v[1] * v[1];
        let t3 = v[3] * v[3];
        let t4 = v[0] * v[7];
        let t7 = v[3] * v[6];
        let t8 = v[0].mul_add(v[0], t1);
        let t9 = v[2].mul_add(v[2], t3);
        let t10 = t8 + t9;
        let t11 = (-v[1]).mul_add(v[4], t4);
        let t12 = v[2].mul_add(v[5], t7);
        let t13 = t11 - t12;
        let t14 = xv[0] * t10;
        let t15 = xv[0] * t13;
        let t16 = t15 * T::from_i64(2);
            return Motor { c: gx::slots::from_values::<S, T, 8>([t14, T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), t16]) };
        }
        let m1 = v[1] * v[1];
        let m3 = v[3] * v[3];
        let m4 = v[0] * v[7];
        let m7 = v[3] * v[6];
        let m8 = v[0].mul_add(v[0], m1);
        let m9 = v[2].mul_add(v[2], m3);
        let m10 = m8 + m9;
        let m11 = (-v[1]).mul_add(v[4], m4);
        let m12 = v[2].mul_add(v[5], m7);
        let m13 = m11 - m12;
        let m14 = m13 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m10)).0, S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), (x[0].scale(m14)).0] }
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::TransformInv<Scalar<S, T>> for Motor<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform_inv(self, x: Scalar<S, T>) -> Motor<S, T> {
        gx::Transform::transform(self.reverse(), x)
    }
}

impl<T: gx::Coef> gx::Prepare<Scalar> for Motor<(), T> {
    type Output = gx::Prepared<Motor, Scalar, T, 2>;
    #[inline]
    fn prepare(self) -> gx::Prepared<Motor, Scalar, T, 2> {
        let v = self.c;
        let m1 = v[1] * v[1];
        let m3 = v[3] * v[3];
        let m4 = v[0] * v[7];
        let m7 = v[3] * v[6];
        let m8 = v[0].mul_add(v[0], m1);
        let m9 = v[2].mul_add(v[2], m3);
        let m10 = m8 + m9;
        let m11 = (-v[1]).mul_add(v[4], m4);
        let m12 = v[2].mul_add(v[5], m7);
        let m13 = m11 - m12;
        let m14 = m13 * T::from_i64(2);
        gx::Prepared::from_entries([m10, m14])
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::Transform<Scalar<S, T>> for gx::Prepared<Motor, Scalar, T, 2> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Scalar<S, T>) -> Motor<S, T> {
        let m = self.m;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m[0])).0, S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), S::from_flat(&mut |_| T::zero(), 0), (x[0].scale(m[1])).0] }
    }
}

impl<T: gx::Coef> From<gx::Prepared<Motor, Scalar, T, 2>> for Motor<(Scalar,), T> {
    /// The dense map of the prepared action.
    #[inline]
    fn from(p: gx::Prepared<Motor, Scalar, T, 2>) -> Self {
        let m = p.m;
        Motor { c: [[m[0]], [T::zero()], [T::zero()], [T::zero()], [T::zero()], [T::zero()], [T::zero()], [m[1]]] }
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::Transform<Scalar<S, T>> for gx::Unit<Motor<(), T>> {
    type Output = Scalar<S, T>;
    #[inline(always)]
    fn transform(self, x: Scalar<S, T>) -> Scalar<S, T> {
        let v = self.into_inner().c;
        if let Some(xv) = gx::slots::values::<S, T, 1>(&x.c) {
            return Scalar { c: gx::slots::from_values::<S, T, 1>([xv[0]]) };
        }
        let x = x.c.map(gx::SlotArr::<S, T>);
        Scalar { c: [(x[0]).0] }
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::TransformInv<Scalar<S, T>> for gx::Unit<Motor<(), T>> {
    type Output = Scalar<S, T>;
    #[inline(always)]
    fn transform_inv(self, x: Scalar<S, T>) -> Scalar<S, T> {
        gx::Transform::transform(gx::Unit::new_unchecked(self.into_inner().reverse()), x)
    }
}

impl<T: gx::Coef> gx::Prepare<Scalar> for gx::Unit<Motor<(), T>> {
    type Output = gx::Prepared<gx::Unit<Motor>, Scalar, T, 0>;
    #[inline]
    fn prepare(self) -> gx::Prepared<gx::Unit<Motor>, Scalar, T, 0> {
        let v = self.into_inner().c;
        gx::Prepared::from_entries([])
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::Transform<Scalar<S, T>> for gx::Prepared<gx::Unit<Motor>, Scalar, T, 0> {
    type Output = Scalar<S, T>;
    #[inline(always)]
    fn transform(self, x: Scalar<S, T>) -> Scalar<S, T> {
        let m = self.m;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Scalar { c: [(x[0]).0] }
    }
}

impl<T: gx::Coef> From<gx::Prepared<gx::Unit<Motor>, Scalar, T, 0>> for Scalar<(Scalar,), T> {
    /// The dense map of the prepared action.
    #[inline]
    fn from(p: gx::Prepared<gx::Unit<Motor>, Scalar, T, 0>) -> Self {
        let m = p.m;
        Scalar { c: [[T::from_i64(1)]] }
    }
}

